import type { Quiz } from "../types";

export const ppeQuiz: Quiz = {
  key: "ppe",
  title: "Property, Plant & Equipment / Fixed Assets",
  subtitle: "Property, Plant & Equipment / Fixed Assets",
  discipline: "intermediate",
  course: "intermediate",
  questions: [
    {
      id: "4951",
      prompt: `A company issued a purchase order on December 15, Year 1, for a piece of capital equipment that costs $100,000. The capital equipment was shipped from the vendor on December 31, Year 1, and received by the company on January 5, Year 2. The equipment was installed and placed in service on February 1, Year 2.

On what date should the depreciation expense begin?`,
      choices: [
        `December 15, Year 1.`,
        `December 31, Year 1.`,
        `January 5, Year 2.`,
        `February 1, Year 2.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. February 1, Year 2 is correct.</strong> That is the date the equipment was installed and placed in service.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Depreciation begins when an asset is <strong style="color:var(--mx-navy)">placed in service</strong>, meaning it is installed, tested and <strong style="color:var(--mx-navy)">ready for its intended use</strong>. Ordering, shipping and receiving dates do not start the clock, because an asset still in the crate is not yet producing the benefits that depreciation is meant to spread.</p><p style="margin:0 0 18px">Two separate events are being tested here. The asset is <strong style="color:var(--mx-navy)">recorded</strong> when title and risk of loss pass to the buyer, and costs of getting it ready, freight, installation and testing, are <strong style="color:var(--mx-navy)">capitalized</strong> into its cost until that point. The asset then <strong style="color:var(--mx-navy)">begins depreciating</strong> on the in-service date and keeps depreciating thereafter, even in periods when it sits idle.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:12px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">January 5, Year 2</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Equipment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$100,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accounts payable</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$100,000</td></tr></tbody></table></div><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">February, Year 2 (5-year straight line, no salvage)</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciation expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$1,667</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated depreciation</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$1,667</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. December 15, Year 1.</strong> A purchase order is only a commitment, so no asset exists on the books yet.<br /><strong style="color:var(--mx-navy)">B. December 31, Year 1.</strong> Shipment may pass title, but the asset is still in transit and unusable.<br /><strong style="color:var(--mx-navy)">C. January 5, Year 2.</strong> Confuses recording the asset with placing it in service; it still needed installation.</p></div>`,
    },
    {
      id: "4975",
      prompt: `A company sold a piece of manufacturing equipment for $25,000. The equipment was originally purchased for $80,000 and had accumulated depreciation of $60,000 at the time of sale. Calculate the gain or loss on the disposal.`,
      choices: [
        `Gain of $5,000`,
        `Loss of $5,000`,
        `Gain of $15,000`,
        `Loss of $15,000`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Gain of $5,000 is correct.</strong> The $25,000 of proceeds exceeds the equipment's $20,000 carrying amount by $5,000.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A disposal gain or loss is measured against the asset's <strong style="color:var(--mx-navy)">carrying amount</strong>, never its original cost. Carrying amount is <strong style="color:var(--mx-navy)">cost less accumulated depreciation</strong>, so build that number first, then subtract it from the proceeds. A positive result is a <strong style="color:var(--mx-navy)">gain</strong>, a negative result is a <strong style="color:var(--mx-navy)">loss</strong>.</p><p style="margin:0 0 18px">The entry removes both the asset and its related accumulated depreciation at their <strong style="color:var(--mx-navy)">full recorded amounts</strong>, so the plug that balances the entry is the gain or loss. Here $60,000 of the $80,000 cost has already run through depreciation, leaving only <strong style="color:var(--mx-navy)">$20,000 of unrecovered cost</strong>, which is why a $25,000 sale price generates income rather than a loss.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Original cost</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$80,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Accumulated depreciation</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(60,000)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Carrying amount at sale</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">20,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Proceeds</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">25,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Gain, $25,000 less $20,000</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$5,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Cash</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$25,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Accumulated depreciation</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">60,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Equipment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$80,000</td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Gain on disposal</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">5,000</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Loss of $5,000.</strong> Right size, wrong direction: proceeds are above carrying amount, not below.<br /><strong style="color:var(--mx-navy)">C. Gain of $15,000.</strong> Understates carrying amount at $10,000 instead of $20,000.<br /><strong style="color:var(--mx-navy)">D. Loss of $15,000.</strong> Compares the proceeds to an inflated $40,000 carrying amount and flips the sign as well.</p></div>`,
    },
    {
      id: "8349",
      prompt: `MegaManufacturing Inc. bought factory machinery for $120,000 on January 1, Year 1. The machinery has a useful life of 10 years and a salvage value of $10,000. Using the double declining balance method, what is the net book value of the machinery at the end of Year 3?`,
      choices: [
        `$61,440`,
        `$65,520`,
        `$70,000`,
        `$75,000`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. $61,440 is correct.</strong> Three years of depreciation at 20% of the beginning book value reduce $120,000 to $61,440.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Double declining balance applies <strong style="color:var(--mx-navy)">twice the straight-line rate</strong> to the book value at the start of each year. A 10-year life gives a straight-line rate of 10%, so the <strong style="color:var(--mx-navy)">DDB rate is 20%</strong>. The rate never changes; only the base does, and that base shrinks every year.</p><p style="margin:0 0 18px"><strong style="color:var(--mx-navy)">Salvage value is not subtracted from cost</strong> under this method. It acts only as a <strong style="color:var(--mx-navy)">floor</strong>: depreciation stops once book value reaches $10,000. Book value here stays well above $10,000 through Year 3, so the floor never bites. Depreciating $110,000 instead of the full $120,000 is the classic error, because declining balance always works off <strong style="color:var(--mx-navy)">cost less accumulated depreciation to date</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Year</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Beginning book value</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Depreciation at 20%</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Ending book value</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$120,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$24,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$96,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 2</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$96,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$19,200</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$76,800</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 3</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$76,800</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$15,360</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$61,440</td></tr><tr><td style="border:0; padding:11px 14px" colspan="3"><strong style="color:var(--mx-navy)">Net book value, end of Year 3</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$61,440</strong></td></tr></tbody></table></div><p style="margin:0 0 18px">A faster route skips the schedule: book value keeps <strong style="color:var(--mx-navy)">80% of its prior balance</strong> each year, so after three years it is $120,000 x 0.80 x 0.80 x 0.80, or $120,000 x 0.512, which is $61,440.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The Year 3 entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciation expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$15,360</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated depreciation</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$15,360</td></tr></tbody></table></div><p style="margin:0">Accumulated depreciation after three years totals <strong style="color:var(--mx-navy)">$58,560</strong>, and $120,000 less $58,560 gives the $61,440 carrying amount.</p></div>`,
    },
    {
      id: "4953",
      prompt: `Tomson Co. installed new assembly line production equipment at a cost of $175,000. To prepare for the installation, Tomson had to rearrange the existing assembly line at a cost of $12,000 and remove a wall at a cost of $3,000. The rearrangement and wall removal were necessary to accommodate the new equipment. The rearrangement did not increase the life of the existing assembly line but did make the production process more efficient with the new equipment in place.

What is the total cost of the new equipment to be capitalized?`,
      choices: [
        `$175,000`,
        `$178,000`,
        `$187,000`,
        `$190,000`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. $190,000 is correct.</strong> Every cost needed to get the equipment in place and ready for its intended use is capitalized, including the wall removal and the rearrangement.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">The cost of a fixed asset is its <strong style="color:var(--mx-navy)">purchase price</strong> plus every cost <strong style="color:var(--mx-navy)">necessary to bring the asset to the location and condition</strong> needed for its intended use. That includes freight, sales tax, installation, testing before operation, and any modification to the building or plant layout required to fit the asset in. Start from the invoice price and ask one question about each additional outlay: would the equipment be ready for use without it?</p><p style="margin:0 0 12px">The trap is the <strong style="color:var(--mx-navy)">rearrangement</strong>. Rearranging existing equipment is normally a period expense, but here the move was <strong style="color:var(--mx-navy)">required to accommodate</strong> the new production line, so it is a cost of readying the new asset. Two facts in the stem are deliberate noise: the rearrangement <strong style="color:var(--mx-navy)">did not extend the life</strong> of the old assembly line, and it made production <strong style="color:var(--mx-navy)">more efficient</strong>. Neither changes the answer, because the only test is necessity for the new equipment.</p><p style="margin:0 0 18px">If Tomson had moved the line later simply to tidy the floor, with no new asset involved, the $12,000 would hit expense. Costs that fail the necessity test, such as <strong style="color:var(--mx-navy)">employee training</strong>, damage repairs during installation, or insurance once the asset is running, are <strong style="color:var(--mx-navy)">expensed as incurred</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Equipment purchase price</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$175,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Wall removal, required for installation</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">3,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Rearrangement to accommodate the new line</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">12,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Total capitalized cost</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$190,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Assembly line equipment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$190,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash or accounts payable</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$190,000</td></tr></tbody></table></div><p style="margin:0">The full $190,000 sits in the equipment account and is <strong style="color:var(--mx-navy)">depreciated over the equipment's useful life</strong>.</p></div>`,
    },
    {
      id: "9432",
      prompt: `Sky Inc. determined that due to the introduction of newer technology, the useful life of an existing piece of machinery needed to be revised. The machinery originally cost $1,500,000, and total accumulated depreciation recorded through January 1, Year 7, was $700,000. On that date, the remaining lifespan of the machinery was reduced from its original estimate to 4 remaining years. Given that the straight-line depreciation method is used with zero estimated residual value, what total amount should Sky report as accumulated depreciation in its December 31, Year 7, balance sheet?`,
      choices: [
        `$725,000`,
        `$750,000`,
        `$775,000`,
        `$900,000`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. $900,000 is correct.</strong> The $700,000 already recorded stays on the books, and Year 7 adds $200,000 of new depreciation.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Revising a useful life is a <strong style="color:var(--mx-navy)">change in accounting estimate</strong>, and estimate changes are applied <strong style="color:var(--mx-navy)">prospectively</strong> (<strong style="color:var(--mx-navy)">ASC 250</strong>). Prior years are never restated, so the existing accumulated depreciation balance is left exactly as it is.</p><p style="margin:0 0 18px">Going forward, spread the <strong style="color:var(--mx-navy)">carrying amount on the revision date</strong>, less any salvage value, over the <strong style="color:var(--mx-navy)">new remaining life</strong>. Note what you are not given: the original useful life and the purchase date. You do not need them, and that omission is deliberate. Cost minus accumulated depreciation gives the $800,000 book value, and four years is the only life that matters now.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Original cost</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$1,500,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less accumulated depreciation, January 1, Year 7</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(700,000)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Book value to depreciate</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">800,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 7 expense, $800,000 / 4 years</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">200,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Add back opening accumulated depreciation</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">700,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Accumulated depreciation, December 31, Year 7</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$900,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry for Year 7</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciation expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$200,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated depreciation</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$200,000</td></tr></tbody></table></div><p style="margin:0">The balance sheet then shows machinery of $1,500,000 less accumulated depreciation of $900,000, a <strong style="color:var(--mx-navy)">net carrying amount of $600,000</strong>, which is the remaining three years at $200,000 each.</p></div>`,
    },
    {
      id: "4972",
      prompt: `A company purchased machinery on April 1, Year 1, for $100,000 and incurred installation costs of $20,000. The machinery has a useful life of 10 years and a salvage value of $10,000. The company uses straight-line depreciation. Calculate the net book value of the machinery at the end of Year 2.`,
      choices: [
        `$101,500`,
        `$104,000`,
        `$100,750`,
        `$106,500`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $100,750 is correct.</strong> Cost of $120,000 less nine months plus a full year of depreciation, $19,250, leaves $100,750.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Capitalize every cost needed to get the asset <strong style="color:var(--mx-navy)">ready for its intended use</strong>, so the $20,000 of installation joins the $100,000 price in the machinery account. Straight-line depreciation then spreads the <strong style="color:var(--mx-navy)">depreciable base</strong>, capitalized cost less salvage value, evenly over the useful life.</p><p style="margin:0 0 18px">Two traps live here. Salvage value is subtracted <strong style="color:var(--mx-navy)">once</strong>, inside the depreciation calculation, never again from book value. And an asset bought on April 1 earns only <strong style="color:var(--mx-navy)">nine months</strong> of expense in Year 1, with a full twelve months in Year 2. Net book value is always <strong style="color:var(--mx-navy)">gross cost less accumulated depreciation</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Purchase price</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$100,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Installation costs</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">20,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Capitalized cost</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$120,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less salvage value</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(10,000)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciable base</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$110,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Annual depreciation, $110,000 / 10 years</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$11,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 1, $11,000 x 9/12</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">8,250</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 2, full year</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">11,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Accumulated depreciation</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$19,250</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Net book value, $120,000 - $19,250</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$100,750</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at December 31, Year 2</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciation expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$11,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated depreciation, machinery</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$11,000</td></tr></tbody></table></div><p style="margin:0 0 12px">The machinery account stays at $120,000 for all ten years. Only the <strong style="color:var(--mx-navy)">contra account</strong> grows, and book value stops falling at the $10,000 salvage floor.</p></div>`,
    },
    {
      id: "8351",
      prompt: `GlobalTech Inc. purchased manufacturing equipment for $500,000. After several years of use, due to technological advancements, the estimated future cash flows from the use of this equipment have been significantly reduced. At the end of the current year, the estimated future cash flows from the equipment are projected to be $300,000, and the fair value of the equipment is estimated to be $280,000. The carrying amount of the equipment at this time is $400,000. What is the impairment loss on the manufacturing equipment to be recognized in the financial statements?`,
      choices: [
        `$100,000`,
        `$120,000`,
        `$200,000`,
        `$220,000`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. $120,000 is correct.</strong> The equipment fails the recoverability test, so the impairment loss equals carrying amount less fair value.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Impairment testing for a long-lived asset <strong style="color:var(--mx-navy)">held for use</strong> runs in two steps (<strong style="color:var(--mx-navy)">ASC 360</strong>). Step one is the <strong style="color:var(--mx-navy)">recoverability test</strong>: compare the carrying amount with the total <strong style="color:var(--mx-navy)">undiscounted future cash flows</strong> the asset is expected to generate. If those cash flows equal or exceed the carrying amount, the asset is not impaired and nothing is recorded, no matter how far fair value has fallen.</p><p style="margin:0 0 18px">Step two runs only when step one fails. The loss is then measured as <strong style="color:var(--mx-navy)">carrying amount minus fair value</strong>, never carrying amount minus the cash flows. The cash flows are the <strong style="color:var(--mx-navy)">trigger</strong>; fair value is the <strong style="color:var(--mx-navy)">measurement</strong>. Here the $300,000 of expected cash flows falls short of the $400,000 carrying amount, so the equipment is impaired and is written down to its $280,000 fair value.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Carrying amount</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$400,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Undiscounted future cash flows</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$300,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Step 1: carrying amount exceeds cash flows</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">Impaired</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less fair value</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(280,000)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Impairment loss</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$120,000</strong></td></tr></tbody></table></div><p style="margin:0 0 18px">The $100,000 spread between the original $500,000 cost and the $400,000 carrying amount is depreciation already recorded and plays no part in measuring the loss.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Loss on impairment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$120,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated impairment, equipment</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$120,000</td></tr></tbody></table></div><p style="margin:0">The $280,000 becomes the asset's <strong style="color:var(--mx-navy)">new cost basis</strong>, depreciated over the remaining useful life. The loss hits <strong style="color:var(--mx-navy)">income from continuing operations</strong>, and under US GAAP a later recovery in value <strong style="color:var(--mx-navy)">cannot be reversed</strong>.</p></div>`,
    },
    {
      id: "4970",
      prompt: `Last year, Katt Co. reduced the carrying amount of its long-lived assets used in operations from $120,000 to $100,000, in connection with its annual impairment review. During the current year, Katt determined that the fair value of the same assets had increased to $130,000.

What amount should Katt record as restoration of previously recognized impairment loss in the current year's financial statements under U.S. GAAP?`,
      choices: [
        `$0`,
        `$10,000`,
        `$20,000`,
        `$30,000`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. $0 is correct.</strong> U.S. GAAP prohibits reversing an impairment loss once it has been recognized on long-lived assets held for use.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Testing an asset held and used is a two-step process (<strong style="color:var(--mx-navy)">ASC 360</strong>): compare the carrying amount to the <strong style="color:var(--mx-navy)">undiscounted future cash flows</strong> to decide whether an impairment exists, then measure the loss as carrying amount minus <strong style="color:var(--mx-navy)">fair value</strong>. Once that write-down is booked, the reduced amount becomes the asset's <strong style="color:var(--mx-navy)">new cost basis</strong> and is depreciated over the remaining useful life.</p><p style="margin:0 0 18px">That new basis is <strong style="color:var(--mx-navy)">never written back up</strong>. Here the recovery to $130,000 sits $30,000 above the $100,000 carrying amount and $10,000 above the original $120,000, and none of it is recorded. Katt picks up the appreciation only when the assets are <strong style="color:var(--mx-navy)">sold or disposed of</strong>, as a larger gain at that date. IFRS permits a limited reversal, capped at the depreciated original carrying amount, but the question asks for U.S. GAAP.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Carrying amount before impairment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$120,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Impairment loss recorded last year</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(20,000)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">New cost basis carried forward</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$100,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Current fair value</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$130,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Restoration recognized this year</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$0</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry last year</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Impairment loss</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$20,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Long-lived assets</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$20,000</td></tr></tbody></table></div><p style="margin:0 0 12px">No entry is made in the current year. The $100,000 basis keeps being depreciated and the $20,000 loss stays in last year's income permanently.</p><p style="margin:0">One narrow exception worth knowing: assets classified as <strong style="color:var(--mx-navy)">held for sale</strong> are carried at the lower of carrying amount or fair value less cost to sell, and a later recovery can be restored up to the cumulative losses already taken. Katt's assets are <strong style="color:var(--mx-navy)">used in operations</strong>, so that exception does not apply.</p></div>`,
    },
    {
      id: "8167",
      prompt: `Quantum Mechanics Inc. purchased a machine for $500,000 on January 1, 2021. The machine was estimated to have a useful life of 100,000 hours and a residual value of $50,000. During the first two years of operations, the machine was used for 15,000 hours in 2021 and 20,000 hours in 2022. On December 31, 2022, Quantum sold the machine for $370,000. What is the gain or loss on the sale of the machine?`,
      choices: [
        `Gain of $10,000`,
        `Loss of $10,000`,
        `Gain of $27,500`,
        `Loss of $27,500`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. Gain of $27,500 is correct.</strong> The $370,000 of proceeds exceeded the $342,500 book value left after two years of hours-based depreciation.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Under the <strong style="color:var(--mx-navy)">units-of-production</strong> method, the depreciable base is <strong style="color:var(--mx-navy)">cost less residual value</strong>, spread over total expected output. Divide that base by the 100,000 estimated hours to get a rate per hour, then multiply by <strong style="color:var(--mx-navy)">actual hours used</strong> each year. Residual value is never depreciated.</p><p style="margin:0 0 18px">On disposal, the gain or loss is simply <strong style="color:var(--mx-navy)">proceeds minus book value</strong>, and book value is cost less <strong style="color:var(--mx-navy)">accumulated depreciation</strong>. Residual value does not enter the disposal math a second time: it has already done its work by limiting how much depreciation was taken. Proceeds above book value are a <strong style="color:var(--mx-navy)">gain</strong>; proceeds below book value are a loss.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Rate per hour, ($500,000 - $50,000) / 100,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$4.50</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">2021 depreciation, 15,000 hours</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$67,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">2022 depreciation, 20,000 hours</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$90,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Book value, $500,000 - $157,500</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$342,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Proceeds</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$370,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Gain on sale</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$27,500</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at December 31, 2022</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Cash</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$370,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Accumulated depreciation</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$157,500</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Machine</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$500,000</td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Gain on sale of machine</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$27,500</td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Gain of $10,000.</strong> Uses a mis-stated rate per hour; at $4.50 accumulated depreciation is $157,500, not the $140,000 this figure implies.<br /><strong style="color:var(--mx-navy)">B. Loss of $10,000.</strong> Same bad rate, plus a reversed sign, since proceeds exceed book value.<br /><strong style="color:var(--mx-navy)">D. Loss of $27,500.</strong> Right amount, wrong direction: selling above book value produces a gain.</p></div>`,
    },
    {
      id: "4954",
      prompt: `Cart Co. purchased an office building and the land on which it is located for $750,000 cash and an existing $250,000 mortgage. For realty tax purposes, the property is assessed at $960,000, 60% of which is allocated to the building.

At what amount should Cart record the building?`,
      choices: [
        `$500,000`,
        `$576,000`,
        `$600,000`,
        `$960,000`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $600,000 is correct.</strong> The building takes 60% of the $1,000,000 actually paid, not 60% of the tax assessment.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A land and building bought together is a <strong style="color:var(--mx-navy)">basket purchase</strong>. Record the full <strong style="color:var(--mx-navy)">cost</strong> of the package, then split it between the components using their <strong style="color:var(--mx-navy)">relative fair values</strong>. Cost includes cash paid plus any <strong style="color:var(--mx-navy)">mortgage assumed</strong>, because assuming debt is consideration given.</p><p style="margin:0 0 18px">The assessed value is only the <strong style="color:var(--mx-navy)">allocation percentage</strong>, never the recorded amount. Assessed values are used to build the 60/40 ratio, then that ratio is applied to the $1,000,000 price. Land is <strong style="color:var(--mx-navy)">never depreciated</strong>, so getting this split right drives every future depreciation figure.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Cash paid</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$750,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Mortgage assumed</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">250,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Total cost to allocate</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$1,000,000</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Building share of assessed value</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">60%</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Building, $1,000,000 x 60%</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$600,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at acquisition</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Building</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$600,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Land</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">400,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Cash</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$750,000</td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Mortgage payable</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">250,000</td></tr></tbody></table></div><p style="margin:0">Land absorbs the remaining 40%, or $400,000, and the two capitalized amounts always sum back to the $1,000,000 consideration given.</p></div>`,
    },
  ],
};
